package crypto

import (
	"encoding/base64"
	"strings"
	"testing"
)

// Generated by PostgreSQL 16: CREATE ROLE vec PASSWORD 'pencil' with
// password_encryption = scram-sha-256, read from pg_authid.
const pgVerifier = "SCRAM-SHA-256$4096:xZdzQGoD8rPOOiA+nRGhbg==$+WdHWJohwb4+PeAaCScSqLSMpA2KOj/Dxu03Wi5VEUg=:JKcXPW82Wu68TNyJtBgvmoUB9FE/ScpWRW+LZr8Zjow="

func TestSCRAMMatchesPostgres(t *testing.T) {
	salt, _ := base64.StdEncoding.DecodeString("xZdzQGoD8rPOOiA+nRGhbg==")
	got, err := SCRAMVerifierWithSalt("pencil", salt, 4096)
	if err != nil {
		t.Fatal(err)
	}
	if got != pgVerifier {
		t.Fatalf("got  %s\nwant %s", got, pgVerifier)
	}
}

func TestSCRAMVerifierIsSalted(t *testing.T) {
	a, err := SCRAMVerifier("secret")
	if err != nil {
		t.Fatal(err)
	}
	b, _ := SCRAMVerifier("secret")
	if a == b {
		t.Fatal("two verifiers share a salt")
	}
	if !strings.HasPrefix(a, "SCRAM-SHA-256$4096:") || !IsSCRAMVerifier(a) {
		t.Fatalf("bad verifier %q", a)
	}
	if strings.Contains(a, "secret") {
		t.Fatal("verifier contains the password")
	}
}

func TestSCRAMRejectsNonASCII(t *testing.T) {
	if _, err := SCRAMVerifier("pässword"); err == nil {
		t.Fatal("non-ASCII password accepted")
	}
}

func TestIsSCRAMVerifier(t *testing.T) {
	for _, s := range []string{"", "md5abc", "pencil", "SCRAM-SHA-256$x:y$z", "SCRAM-SHA-256$4096:!!$a:b"} {
		if IsSCRAMVerifier(s) {
			t.Errorf("%q accepted", s)
		}
	}
	if !IsSCRAMVerifier(pgVerifier) {
		t.Error("postgres verifier rejected")
	}
}
